def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    ok = [False] * (n + 4)
    ok[0] = True
    for p in range(n):
        if not ok[p]:
            continue
        if p + 1 < n and s[p] == '1':
            ok[p + 1] = True
        if p + 3 < n and s[p] == '2' and s[p + 2] == '1' and s[p + 1] == '2':
            ok[p + 3] = True
    print('YES' if ok[n - 1] else 'NO')

