def gen(rng):
    def fmt(s):
        return str(len(s)) + '\n' + s
    tests = [fmt('1'), fmt('2'), fmt('11'), fmt('21'), fmt('12'), fmt('22111'), fmt('2111'), fmt('121'), fmt('1111')]
    for n in (3, 4, 5, 6, 7, 8, 10, 12, 14):
        for _ in range(3):
            tests.append(fmt(''.join(rng.choice('12') for _ in range(n))))

    def good(n):
        # build a string that is good by concatenating step (1) and zigzag (2 2 1) blocks
        s = []
        while len(s) < n - 1:
            if n - 1 - len(s) >= 3 and rng.random() < 0.5:
                s += ['2', '2', '1']
            else:
                s.append('1')
        s.append(rng.choice('12'))
        return ''.join(s)
    for n in (6, 9, 13, 16):
        tests.append(fmt(good(n)))
    n = 100000
    tests.append(fmt(good(n)))
    tests.append(fmt('1' * n))
    g = list(good(n))
    g[rng.randrange(1, n - 1)] = '2'
    tests.append(fmt(''.join(g)))
    tests.append(fmt('221' * (n // 3) + '1' * (n % 3)))
    return tests

